import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="hero-glow"></div>

      <div className="hero-content">

        <p className="tag">👋 Welcome to my portfolio</p>

        <h1>
          I'm <span className="name">Swetha</span>
        </h1>

        <h2 className="role">
          A Curious Mind Exploring the World of Technology
        </h2>

        <p className="desc">
          Passionate about technology and innovation, always eager to learn,
          create, and build meaningful digital solutions that make an impact.
        </p>

        <div className="buttons">
          <button className="btn primary" onClick={() => navigate("/projects")}>
            Explore Projects →
          </button>

          <button className="btn secondary" onClick={() => navigate("/about")}>
            See My Journey →
          </button>
        </div>

      </div>

      <style>{`

        .hero {
          height: 90vh;
          display: flex;
          align-items: center;
          justify-content: center;
          text-align: center;
          padding: 0 20px;
          position: relative;
          background: radial-gradient(circle at top, #0b1220, #050816);
          overflow: hidden;
        }

        /* SOFT GLOW BACKGROUND */
        .hero-glow {
          position: absolute;
          width: 500px;
          height: 500px;
          background: rgba(56,189,248,0.15);
          filter: blur(120px);
          top: -100px;
          left: 50%;
          transform: translateX(-50%);
          z-index: 0;
        }

        .hero-content {
          max-width: 750px;
          position: relative;
          z-index: 1;
        }

        /* TAG */
        .tag {
          color: #38BDF8;
          font-size: 14px;
          margin-bottom: 15px;
          letter-spacing: 2px;
          text-transform: uppercase;
        }

        /* NAME */
        .hero h1 {
          font-size: 64px;
          font-weight: 700;
          margin-bottom: 10px;
        }

        .name {
          color: #38BDF8;
          text-shadow: 0 0 20px rgba(56,189,248,0.4);
        }

        /* ROLE */
        .role {
          font-size: 22px;
          font-weight: 500;
          color: #94a3b8;
          margin-bottom: 20px;
        }

        /* DESCRIPTION */
        .desc {
          font-size: 17px;
          line-height: 1.8;
          color: #cbd5e1;
          margin-bottom: 40px;
        }

        /* BUTTONS */
        .buttons {
          display: flex;
          gap: 18px;
          justify-content: center;
        }

        .btn {
          padding: 14px 28px;
          font-size: 15px;
          font-weight: 600;
          border-radius: 12px;
          cursor: pointer;
          transition: 0.3s ease;
          border: 1px solid rgba(56,189,248,0.4);
        }

        /* PRIMARY BUTTON */
        .primary {
          background: #38BDF8;
          color: #0b1220;
          box-shadow: 0 0 20px rgba(56,189,248,0.3);
        }

        .primary:hover {
          transform: translateY(-3px);
          box-shadow: 0 0 30px rgba(56,189,248,0.5);
        }

        /* SECONDARY BUTTON */
        .secondary {
          background: rgba(255,255,255,0.04);
          color: #38BDF8;
          backdrop-filter: blur(10px);
        }

        .secondary:hover {
          background: rgba(56,189,248,0.1);
          transform: translateY(-3px);
        }

        /* RESPONSIVE */
        @media (max-width: 768px) {
          .hero h1 {
            font-size: 42px;
          }

          .role {
            font-size: 18px;
          }

          .buttons {
            flex-direction: column;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
